    gone_note: "This event no longer appears in any source (cancelled, sold out and pulled, or renamed). Check before going.",
    to_public: "← Full guide",
    suggest: "Suggest an event", feedback: "Feedback on the site",
    form_event: "Suggest an event", form_feedback: "Feedback on the site",
    fl_event: "What / who", fl_when: "When", fl_where: "Where", fl_link: "Link (Instagram, tickets…)",
    fl_notes: "Anything else?", fl_msg: "Your message", fl_contact: "Contact (optional)", fl_send: "Send",
    fl_sending: "Sending…", fl_sent: "Got it, thanks!", fl_fail: "Couldn't send. Please try again later.",
